CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL UNIQUE,code varchar(30) UNIQUE,description text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid REFERENCES departments(id),name varchar(160) NOT NULL,code varchar(30) UNIQUE,duration_semesters int DEFAULT 6,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS academic_years (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label varchar(30) NOT NULL UNIQUE,starts_on date,ends_on date,is_current boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS semesters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid REFERENCES courses(id),academic_year_id uuid REFERENCES academic_years(id),semester_number int NOT NULL,starts_on date,ends_on date);
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id varchar(20) NOT NULL UNIQUE,first_name varchar(80) NOT NULL,last_name varchar(80) NOT NULL,phone varchar(20) NOT NULL UNIQUE,email varchar(254) NOT NULL UNIQUE,password_hash text NOT NULL,role varchar(20) NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin','examiner')),status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','suspended','pending')),department_id uuid REFERENCES departments(id),course_id uuid REFERENCES courses(id),semester int,avatar_url text,last_login_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS user_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL,ip_address inet,user_agent text,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS password_reset_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS email_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,verification_hash text NOT NULL,expires_at timestamptz NOT NULL,verified_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid REFERENCES departments(id),course_id uuid REFERENCES courses(id),name varchar(160) NOT NULL,code varchar(40) UNIQUE,description text,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,name varchar(160) NOT NULL,description text,display_order int DEFAULT 0);
CREATE TABLE IF NOT EXISTS exam_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL UNIQUE,description text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(160) NOT NULL,settings jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title varchar(200) NOT NULL,description text,instructions text,subject_id uuid REFERENCES subjects(id),category_id uuid REFERENCES exam_categories(id),template_id uuid REFERENCES exam_templates(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,duration_minutes int NOT NULL CHECK(duration_minutes>0),total_marks numeric(9,2) NOT NULL DEFAULT 100,passing_marks numeric(9,2) NOT NULL DEFAULT 40,status varchar(20) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','active','completed','archived')),randomize_questions boolean DEFAULT false,randomize_options boolean DEFAULT false,attempts_allowed int DEFAULT 1,created_by uuid REFERENCES users(id),deleted_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),CHECK(ends_at>starts_at),CHECK(passing_marks<=total_marks));
CREATE TABLE IF NOT EXISTS exam_eligibility (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,student_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,allowed boolean DEFAULT true,reason text,created_at timestamptz DEFAULT now(),UNIQUE(exam_id,student_id));
CREATE TABLE IF NOT EXISTS exam_sections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,title varchar(160) NOT NULL,instructions text,display_order int DEFAULT 0,marks numeric(9,2));
CREATE TABLE IF NOT EXISTS questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,section_id uuid REFERENCES exam_sections(id) ON DELETE SET NULL,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,question_text text NOT NULL,question_type varchar(30) NOT NULL DEFAULT 'mcq',options jsonb NOT NULL DEFAULT '[]'::jsonb,correct_answer jsonb NOT NULL,explanation text,marks numeric(9,2) NOT NULL DEFAULT 1,negative_marks numeric(9,2) NOT NULL DEFAULT 0,display_order int DEFAULT 0,is_active boolean DEFAULT true,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS question_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE,media_url text NOT NULL,media_type varchar(30),alt_text text,display_order int DEFAULT 0);
CREATE TABLE IF NOT EXISTS question_tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS question_tag_links (question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE,tag_id uuid NOT NULL REFERENCES question_tags(id) ON DELETE CASCADE,PRIMARY KEY(question_id,tag_id));
CREATE TABLE IF NOT EXISTS exam_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES exams(id),student_id uuid NOT NULL REFERENCES users(id),attempt_number int NOT NULL DEFAULT 1,status varchar(25) NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','submitted','auto_submitted','graded','voided')),started_at timestamptz DEFAULT now(),expires_at timestamptz NOT NULL,submitted_at timestamptz,time_taken_seconds int,ip_address inet,created_at timestamptz DEFAULT now(),UNIQUE(exam_id,student_id,attempt_number));
CREATE TABLE IF NOT EXISTS student_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES exam_attempts(id) ON DELETE CASCADE,question_id uuid NOT NULL REFERENCES questions(id),answer_json jsonb,is_marked_for_review boolean DEFAULT false,saved_at timestamptz DEFAULT now(),UNIQUE(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS answer_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES exam_attempts(id) ON DELETE CASCADE,question_id uuid REFERENCES questions(id),event_type varchar(40) NOT NULL,event_data jsonb DEFAULT '{}'::jsonb,occurred_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL UNIQUE REFERENCES exam_attempts(id),student_id uuid NOT NULL REFERENCES users(id),exam_id uuid NOT NULL REFERENCES exams(id),marks_obtained numeric(9,2) DEFAULT 0,total_marks numeric(9,2) NOT NULL,percentage numeric(5,2) DEFAULT 0,result_status varchar(20) NOT NULL CHECK(result_status IN ('pass','fail','pending','absent')),correct_count int DEFAULT 0,incorrect_count int DEFAULT 0,answered_count int DEFAULT 0,evaluator_remarks text,published_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS result_subject_breakdown (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),result_id uuid NOT NULL REFERENCES results(id) ON DELETE CASCADE,subject_id uuid REFERENCES subjects(id),marks_obtained numeric(9,2) DEFAULT 0,total_marks numeric(9,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS grade_scales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL,min_percentage numeric(5,2) NOT NULL,max_percentage numeric(5,2) NOT NULL,grade_label varchar(10) NOT NULL,description text,CHECK(max_percentage>=min_percentage));
CREATE TABLE IF NOT EXISTS certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES users(id),result_id uuid NOT NULL REFERENCES results(id),certificate_number varchar(80) NOT NULL UNIQUE,issued_at timestamptz DEFAULT now(),file_url text,revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title varchar(200) NOT NULL,body text NOT NULL,type varchar(30) DEFAULT 'info',read_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title varchar(200) NOT NULL,body text NOT NULL,audience varchar(30) DEFAULT 'all',starts_at timestamptz,ends_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS announcement_reads (announcement_id uuid NOT NULL REFERENCES announcements(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,read_at timestamptz DEFAULT now(),PRIMARY KEY(announcement_id,user_id));
CREATE TABLE IF NOT EXISTS support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),subject varchar(200) NOT NULL,description text NOT NULL,priority varchar(20) DEFAULT 'normal',status varchar(20) DEFAULT 'open',assigned_to uuid REFERENCES users(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id),message text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(80) NOT NULL UNIQUE,permissions jsonb DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS admin_role_assignments (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE,assigned_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,action varchar(100) NOT NULL,entity_type varchar(80) NOT NULL,entity_id uuid,metadata jsonb DEFAULT '{}'::jsonb,ip_address inet,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS system_settings (key varchar(120) PRIMARY KEY,value jsonb NOT NULL DEFAULT '{}'::jsonb,updated_by uuid REFERENCES users(id),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_proctor_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES exam_attempts(id) ON DELETE CASCADE,event_type varchar(80) NOT NULL,details jsonb DEFAULT '{}'::jsonb,reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_accommodations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,student_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,extra_time_minutes int DEFAULT 0,notes text,approved_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now(),UNIQUE(exam_id,student_id));
CREATE TABLE IF NOT EXISTS exam_invigilators (exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,invigilator_id uuid NOT NULL REFERENCES users(id),assigned_at timestamptz DEFAULT now(),PRIMARY KEY(exam_id,invigilator_id));
CREATE TABLE IF NOT EXISTS file_uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),uploaded_by uuid REFERENCES users(id),storage_key text NOT NULL,original_name text NOT NULL,mime_type varchar(120),size_bytes bigint,checksum varchar(128),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,key_hash text NOT NULL,scopes jsonb DEFAULT '[]'::jsonb,last_used_at timestamptz,expires_at timestamptz,revoked_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS scheduled_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_type varchar(80) NOT NULL,payload jsonb DEFAULT '{}'::jsonb,run_at timestamptz NOT NULL,status varchar(20) DEFAULT 'pending',attempts int DEFAULT 0,last_error text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS data_export_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requested_by uuid NOT NULL REFERENCES users(id),export_type varchar(80) NOT NULL,filters jsonb DEFAULT '{}'::jsonb,status varchar(20) DEFAULT 'queued',file_url text,expires_at timestamptz,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_users_role_status ON users(role,status);
CREATE INDEX IF NOT EXISTS idx_exams_schedule ON exams(starts_at,ends_at,status) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_questions_exam_order ON questions(exam_id,display_order);
CREATE INDEX IF NOT EXISTS idx_attempts_student ON exam_attempts(student_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_answers_attempt ON student_answers(attempt_id);
CREATE INDEX IF NOT EXISTS idx_results_student ON results(student_id,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_logs(actor_user_id,created_at DESC);
